<script setup lang="ts">
import { computed,ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { OrderStatus,type OrderSummary } from '@express-platform/shared-types'; import { courierApi } from '../../services/api'; import { requireCourier,useCourierAuth } from '../../stores/auth'; import { errorMessage,formatTime,statusLabel } from '../../utils';
const auth=useCourierAuth(); const orders=ref<OrderSummary[]>([]); const loading=ref(true); const error=ref(''); const tab=ref<'pending'|'mine'|'history'>('pending');
const visible=computed(()=>tab.value==='pending'?orders.value.filter(o=>o.status===OrderStatus.PENDING_ACCEPTANCE):tab.value==='history'?orders.value.filter(o=>[OrderStatus.COMPLETED,OrderStatus.CANCELLED].includes(o.status)):orders.value.filter(o=>![OrderStatus.PENDING_ACCEPTANCE,OrderStatus.COMPLETED,OrderStatus.CANCELLED].includes(o.status)));
onShow(()=>{if(requireCourier())void load();}); async function load():Promise<void>{loading.value=true;error.value='';try{orders.value=await courierApi.orders();}catch(cause:unknown){error.value=errorMessage(cause);}finally{loading.value=false;}} function open(id:string):void{uni.navigateTo({url:`/pages/order-detail/index?id=${encodeURIComponent(id)}`});}
</script>
<template><view class="page"><view class="topbar"><view><text class="hello">{{auth.subject?.displayName??'配送员'}}，辛苦了</text><text class="area">万象测试服务区 · 在线</text></view><text class="mock-pill">● 模拟环境</text></view><view class="work-hero"><view><text class="hero-label">TODAY'S WORK</text><text class="hero-number">{{orders.filter(o=>![OrderStatus.COMPLETED,OrderStatus.CANCELLED].includes(o.status)).length}}</text><text class="hero-copy">当前可处理任务</text></view><view class="availability"><i></i><text>接单中</text></view></view><view class="quick-stats card"><view><strong>{{orders.filter(o=>o.status===OrderStatus.PENDING_ACCEPTANCE).length}}</strong><text>待接单</text></view><view><strong>{{orders.filter(o=>o.status===OrderStatus.IN_TRANSIT).length}}</strong><text>配送中</text></view><view><strong>{{orders.filter(o=>o.status===OrderStatus.COMPLETED).length}}</strong><text>已完成</text></view></view><view class="tabs"><view :class="{active:tab==='pending'}" @tap="tab='pending'">待接订单</view><view :class="{active:tab==='mine'}" @tap="tab='mine'">进行中</view><view :class="{active:tab==='history'}" @tap="tab='history'">历史</view></view><view v-if="loading" class="state-panel card"><text class="state-title">正在同步任务</text><text>从调度中心获取最新订单…</text></view><view v-else-if="error" class="state-panel error-panel"><text class="state-title">任务加载失败</text><text>{{error}}</text><button class="secondary-button retry" @tap="load">重新加载</button></view><view v-else-if="visible.length===0" class="state-panel card"><text class="state-title">当前没有任务</text><text>{{tab==='pending'?'等待管理员分配订单。':'完成的任务会记录在这里。'}}</text></view><view v-else><view v-for="order in visible" :key="order.id" class="task-card card" @tap="open(order.id)"><view class="task-head"><text class="order-no">{{order.orderNo}}</text><text class="status-badge">{{statusLabel[order.status]}}</text></view><view class="route"><view><i>取</i><text>待查看寄件地址</text></view><view class="route-line"></view><view><i class="end">送</i><text>待查看收件地址</text></view></view><view class="task-foot"><text>{{formatTime(order.scheduledPickupAt)}}</text><text class="open">查看任务 →</text></view></view></view><button class="logout" @tap="auth.logout">退出配送员账号</button></view></template>
<style scoped>
